window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-cfebc6be27fb2711"]={"versions": [{"id": "FIG-cfebc6be27fb2711", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> PDU-Layout / Protokoll-Header-Spezifikation (Bit-/Byte-Felddefinition auf Protokollebene).\n</li><li><strong>Architektur-Kontext:</strong> \n<ul class=\"fig-list\"><li><strong>Plattform &amp; Schicht:</strong> AUTOSAR Classic Platform (Release R3.2.3), Communication Stack (ComStack).\n</li><li><strong>Modul:</strong> <code>FrArTp</code> (AUTOSAR FlexRay Transport Layer, Spezifikation SWS_FlexRayARTransportLayer nach ISO 10681-2).\n</li><li><strong>Funktionale Einordnung:</strong> Liegt zwischen dem PDU Router (<code>PduR</code>) als oberer Schicht und dem FlexRay Interface (<code>FrIf</code>) als unterer Schicht.\n</li><li><strong>Technischer Zweck:</strong> Definition des 32-Bit-Adress-Headers für N-PDUs im 2-Byte-Adressierungsmodus (<code>FRARTP_2_BYTE_ADDRESSING</code>). Dient der logischen Adressierung (Quell- und Ziel-Knotenidentifikation) für Punkt-zu-Punkt- (1:1) sowie Punkt-zu-Multipunkt-Verbindungen (1:n, funktional/Broadcast) über FlexRay-Netzwerke, typischerweise für Diagnosekommunikation (DoFR / UDS via ISO 14229) und Kalibrierung (XCP on FlexRay).\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Dargestellte Datenstrukturen &amp; Felder:</strong>\n<ul class=\"fig-list\"><li><strong><code>Target Address (16 Bit)</code>:</strong>\n<ul class=\"fig-list\"><li><strong>Größe:</strong> 2 Byte (16 Bit).\n</li><li><strong>Position:</strong> Byte 0 und Byte 1 des Adress-Headers.\n</li><li><strong>Codierung:</strong> Big-Endian (Network Byte Order, MSB in Byte 0, LSB in Byte 1).\n</li><li><strong>Semantik:</strong> Logische 16-Bit-Zieladresse (Empfänger-Steuergerät bzw. funktionale Multicast-/Broadcast-Adresse).\n</li></ul>\n</li><li><strong><code>Source Address (16 Bit)</code>:</strong>\n<ul class=\"fig-list\"><li><strong>Größe:</strong> 2 Byte (16 Bit).\n</li><li><strong>Position:</strong> Byte 2 und Byte 3 des Adress-Headers.\n</li><li><strong>Codierung:</strong> Big-Endian (Network Byte Order, MSB in Byte 2, LSB in Byte 3).\n</li><li><strong>Semantik:</strong> Logische 16-Bit-Quelladresse (sendendes Steuergerät).\n</li></ul>\n</li></ul>\n</li><li><strong>Beziehungen, Framing &amp; Kardinalitäten:</strong>\n<ul class=\"fig-list\"><li><strong>Gesamtbreite des Adress-Headers:</strong> Exakt 4 Byte.\n</li><li><strong>Kardinalität:</strong> 1:1-Paarung pro adressiertem N-PDU-Rahmen. Jeder Adress-Header besteht obligatorisch aus genau einer Target Address und genau einer Source Address.\n</li><li><strong>PDU-Strukturierung:</strong> Der Adress-Header steht unmittelbar am Anfang der N-PDU, gefolgt von der Protocol Control Information (N-PCI) und den Nutzdaten (N-Data):\n $$\\text{N-PDU} = \\text{Address Header (4 Bytes)} + \\text{N-PCI (1–5 Bytes)} + \\text{N-Data}$$\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Sende-Pfad (TX):</strong>\n<ol class=\"fig-list\"><li><strong>Trigger:</strong> <code>PduR</code> initiiert die Übertragung via <code>PduR_FrArTpTransmit(TxPduId, PduInfoPtr)</code>.\n</li><li><strong>Header-Generierung:</strong> Das Modul <code>FrArTp</code> prüft die für die Verbindung (<code>FrArTpConnection</code>) konfigurierte Adressierungsart. Bei aktivem 2-Byte-Format werden die konfigurierte Target Address (<code>FrArTpTargetAddress</code>) in Byte 0–1 und die Source Address (<code>FrArTpSourceAddress</code>) in Byte 2–3 des N-PDU-Puffers serialisiert.\n</li><li><strong>Framing &amp; N-PCI:</strong> Nachfolgend werden N-PCI (SF, FF, CF, FC) und SDU-Daten assembliert.\n</li><li><strong>Übergabe:</strong> Die serialisierte PDU wird via <code>FrIf_Transmit(FrTxPduId, &amp;PduInfo)</code> an das FlexRay-Interface übergeben.\n</li></ol>\n</li><li><strong>Empfangs-Pfad (RX) &amp; Filterung:</strong>\n<ol class=\"fig-list\"><li><strong>Trigger:</strong> Asynchrone Empfangsmeldung via <code>FrArTp_RxIndication(RxPduId, PduInfoPtr)</code> durch das <code>FrIf</code>.\n</li><li><strong>Parsing:</strong> Extraktion von Byte 0–1 (TA) und Byte 2–3 (SA).\n</li><li><strong>Adressfilterung:</strong> Abgleich von TA gegen die eigene konfigurierte Knotenadresse (physikalisch) oder Gruppenadressen (funktional).\n</li><li><strong>Routing:</strong> Zuordnung zur entsprechenden RX-Verbindungsinstanz (<code>FrArTpRxConnection</code>) anhand des Tupels <code>(Target Address, Source Address)</code>.\n</li><li><strong>Verwerfen/Fehlerfall:</strong> Passt TA nicht auf den lokalen Knoten oder ist kein passender Verbindungskontext konfiguriert, wird die PDU stillschweigend verworfen; bei Formatinkonsistenz oder PDU-Längenunterschreitung (&lt; 4 Byte Adress-Header + N-PCI) erfolgt ein Report an das Default Error Tracer Modul (<code>DET</code>).\n</li></ol>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Nutzdaten-Overhead &amp; PDU-Budgetierung:</strong>\n<ul class=\"fig-list\"><li>Der 2-Byte-Adress-Header verbraucht stets <strong>4 Byte Payload</strong> pro FlexRay-Frame. Bei festen statischen Slotgrößen (z. B. 16, 32 oder 64 Bytes) reduziert sich die maximale Transportdatenlänge pro Frame (Single Frame oder Consecutive Frame) entsprechend um 4 Bytes plus N-PCI-Länge.\n</li></ul>\n</li><li><strong>Endianness &amp; Byte-Order:</strong>\n<ul class=\"fig-list\"><li>AUTOSAR ComStack schreibt Network Byte Order (Big-Endian) vor. Treiber- und Stack-Entwickler müssen sicherstellen, dass 16-Bit-Ganzzahlwerte auf Little-Endian-Mikrocontrollern (z. B. ARM, TriCore) beim Serialisieren/Deserialisieren explizit gedreht werden.\n</li></ul>\n</li><li><strong>Konfigurationsanforderungen (BSW/ECUC):</strong>\n<ul class=\"fig-list\"><li>Parameter <code>FrArTpAddressFormatType</code>: Konfiguration auf <code>FRARTP_2_BYTE_ADDRESSING</code>.\n</li><li>Konsistenz zwischen <code>FrArTpTargetAddress</code> / <code>FrArTpSourceAddress</code> und den korrespondierenden Modulen (<code>PduR</code>, <code>Dcm</code>, DoFR).\n</li><li>Unterscheidung zum 1-Byte-Adressierungsmodus (<code>FRARTP_1_BYTE_ADDRESSING</code>): Das 2-Byte-Format erweitert den logischen Adressraum von 256 auf 65.536 Knoten, verdoppelt jedoch den Adress-Header-Overhead von 2 auf 4 Bytes.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-8e478ed3be09459c", "releases": ["R4.1.3", "R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> PDU-Layout / Protokoll-Header-Spezifikation (Bit-/Byte-Felddefinition auf Protokollebene).\n</li><li><strong>Architektur-Kontext:</strong> \n<ul class=\"fig-list\"><li><strong>Plattform &amp; Schicht:</strong> AUTOSAR Classic Platform (Release R3.2.3), Communication Stack (ComStack).\n</li><li><strong>Modul:</strong> <code>FrArTp</code> (AUTOSAR FlexRay Transport Layer, Spezifikation SWS_FlexRayARTransportLayer nach ISO 10681-2).\n</li><li><strong>Funktionale Einordnung:</strong> Liegt zwischen dem PDU Router (<code>PduR</code>) als oberer Schicht und dem FlexRay Interface (<code>FrIf</code>) als unterer Schicht.\n</li><li><strong>Technischer Zweck:</strong> Definition des 32-Bit-Adress-Headers für N-PDUs im 2-Byte-Adressierungsmodus (<code>FRARTP_2_BYTE_ADDRESSING</code>). Dient der logischen Adressierung (Quell- und Ziel-Knotenidentifikation) für Punkt-zu-Punkt- (1:1) sowie Punkt-zu-Multipunkt-Verbindungen (1:n, funktional/Broadcast) über FlexRay-Netzwerke, typischerweise für Diagnosekommunikation (DoFR / UDS via ISO 14229) und Kalibrierung (XCP on FlexRay).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Dargestellte Datenstrukturen &amp; Felder:</strong>\n<ul class=\"fig-list\"><li><strong><code>Target Address (16 Bit)</code>:</strong>\n<ul class=\"fig-list\"><li><strong>Größe:</strong> 2 Byte (16 Bit).\n</li><li><strong>Position:</strong> Byte 0 und Byte 1 des Adress-Headers.\n</li><li><strong>Codierung:</strong> Big-Endian (Network Byte Order, MSB in Byte 0, LSB in Byte 1).\n</li><li><strong>Semantik:</strong> Logische 16-Bit-Zieladresse (Empfänger-Steuergerät bzw. funktionale Multicast-/Broadcast-Adresse).\n</li></ul>\n</li><li><strong><code>Source Address (16 Bit)</code>:</strong>\n<ul class=\"fig-list\"><li><strong>Größe:</strong> 2 Byte (16 Bit).\n</li><li><strong>Position:</strong> Byte 2 und Byte 3 des Adress-Headers.\n</li><li><strong>Codierung:</strong> Big-Endian (Network Byte Order, MSB in Byte 2, LSB in Byte 3).\n</li><li><strong>Semantik:</strong> Logische 16-Bit-Quelladresse (sendendes Steuergerät).\n</li></ul>\n</li></ul>\n</li><li><strong>Beziehungen, Framing &amp; Kardinalitäten:</strong>\n<ul class=\"fig-list\"><li><strong>Gesamtbreite des Adress-Headers:</strong> Exakt 4 Byte.\n</li><li><strong>Kardinalität:</strong> 1:1-Paarung pro adressiertem N-PDU-Rahmen. Jeder Adress-Header besteht obligatorisch aus genau einer Target Address und genau einer Source Address.\n</li><li><strong>PDU-Strukturierung:</strong> Der Adress-Header steht unmittelbar am Anfang der N-PDU, gefolgt von der Protocol Control Information (N-PCI) und den Nutzdaten (N-Data):\n $$\\text{N-PDU} = \\text{Address Header (4 Bytes)} + \\text{N-PCI (1–5 Bytes)} + \\text{N-Data}$$\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Sende-Pfad (TX):</strong>\n<ol class=\"fig-list\"><li><strong>Trigger:</strong> <code>PduR</code> initiiert die Übertragung via <code>PduR_FrArTpTransmit(TxPduId, PduInfoPtr)</code>.\n</li><li><strong>Header-Generierung:</strong> Das Modul <code>FrArTp</code> prüft die für die Verbindung (<code>FrArTpConnection</code>) konfigurierte Adressierungsart. Bei aktivem 2-Byte-Format werden die konfigurierte Target Address (<code>FrArTpTargetAddress</code>) in Byte 0–1 und die Source Address (<code>FrArTpSourceAddress</code>) in Byte 2–3 des N-PDU-Puffers serialisiert.\n</li><li><strong>Framing &amp; N-PCI:</strong> Nachfolgend werden N-PCI (SF, FF, CF, FC) und SDU-Daten assembliert.\n</li><li><strong>Übergabe:</strong> Die serialisierte PDU wird via <code>FrIf_Transmit(FrTxPduId, &amp;PduInfo)</code> an das FlexRay-Interface übergeben.\n</li></ol>\n</li><li><strong>Empfangs-Pfad (RX) &amp; Filterung:</strong>\n<ol class=\"fig-list\"><li><strong>Trigger:</strong> Asynchrone Empfangsmeldung via <code>FrArTp_RxIndication(RxPduId, PduInfoPtr)</code> durch das <code>FrIf</code>.\n</li><li><strong>Parsing:</strong> Extraktion von Byte 0–1 (TA) und Byte 2–3 (SA).\n</li><li><strong>Adressfilterung:</strong> Abgleich von TA gegen die eigene konfigurierte Knotenadresse (physikalisch) oder Gruppenadressen (funktional).\n</li><li><strong>Routing:</strong> Zuordnung zur entsprechenden RX-Verbindungsinstanz (<code>FrArTpRxConnection</code>) anhand des Tupels <code>(Target Address, Source Address)</code>.\n</li><li><strong>Verwerfen/Fehlerfall:</strong> Passt TA nicht auf den lokalen Knoten oder ist kein passender Verbindungskontext konfiguriert, wird die PDU stillschweigend verworfen; bei Formatinkonsistenz oder PDU-Längenunterschreitung (&lt; 4 Byte Adress-Header + N-PCI) erfolgt ein Report an das Default Error Tracer Modul (<code>DET</code>).\n</li></ol>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Nutzdaten-Overhead &amp; PDU-Budgetierung:</strong>\n<ul class=\"fig-list\"><li>Der 2-Byte-Adress-Header verbraucht stets <strong>4 Byte Payload</strong> pro FlexRay-Frame. Bei festen statischen Slotgrößen (z. B. 16, 32 oder 64 Bytes) reduziert sich die maximale Transportdatenlänge pro Frame (Single Frame oder Consecutive Frame) entsprechend um 4 Bytes plus N-PCI-Länge.\n</li></ul>\n</li><li><strong>Endianness &amp; Byte-Order:</strong>\n<ul class=\"fig-list\"><li>AUTOSAR ComStack schreibt Network Byte Order (Big-Endian) vor. Treiber- und Stack-Entwickler müssen sicherstellen, dass 16-Bit-Ganzzahlwerte auf Little-Endian-Mikrocontrollern (z. B. ARM, TriCore) beim Serialisieren/Deserialisieren explizit gedreht werden.\n</li></ul>\n</li><li><strong>Konfigurationsanforderungen (BSW/ECUC):</strong>\n<ul class=\"fig-list\"><li>Parameter <code>FrArTpAddressFormatType</code>: Konfiguration auf <code>FRARTP_2_BYTE_ADDRESSING</code>.\n</li><li>Konsistenz zwischen <code>FrArTpTargetAddress</code> / <code>FrArTpSourceAddress</code> und den korrespondierenden Modulen (<code>PduR</code>, <code>Dcm</code>, DoFR).\n</li><li>Unterscheidung zum 1-Byte-Adressierungsmodus (<code>FRARTP_1_BYTE_ADDRESSING</code>): Das 2-Byte-Format erweitert den logischen Adressraum von 256 auf 65.536 Knoten, verdoppelt jedoch den Adress-Header-Overhead von 2 auf 4 Bytes.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-63e787954ff327e2", "releases": ["R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> PDU-Layout / Protokoll-Header-Spezifikation (Bit-/Byte-Felddefinition auf Protokollebene).\n</li><li><strong>Architektur-Kontext:</strong> \n<ul class=\"fig-list\"><li><strong>Plattform &amp; Schicht:</strong> AUTOSAR Classic Platform (Release R3.2.3), Communication Stack (ComStack).\n</li><li><strong>Modul:</strong> <code>FrArTp</code> (AUTOSAR FlexRay Transport Layer, Spezifikation SWS_FlexRayARTransportLayer nach ISO 10681-2).\n</li><li><strong>Funktionale Einordnung:</strong> Liegt zwischen dem PDU Router (<code>PduR</code>) als oberer Schicht und dem FlexRay Interface (<code>FrIf</code>) als unterer Schicht.\n</li><li><strong>Technischer Zweck:</strong> Definition des 32-Bit-Adress-Headers für N-PDUs im 2-Byte-Adressierungsmodus (<code>FRARTP_2_BYTE_ADDRESSING</code>). Dient der logischen Adressierung (Quell- und Ziel-Knotenidentifikation) für Punkt-zu-Punkt- (1:1) sowie Punkt-zu-Multipunkt-Verbindungen (1:n, funktional/Broadcast) über FlexRay-Netzwerke, typischerweise für Diagnosekommunikation (DoFR / UDS via ISO 14229) und Kalibrierung (XCP on FlexRay).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Dargestellte Datenstrukturen &amp; Felder:</strong>\n<ul class=\"fig-list\"><li><strong><code>Target Address (16 Bit)</code>:</strong>\n<ul class=\"fig-list\"><li><strong>Größe:</strong> 2 Byte (16 Bit).\n</li><li><strong>Position:</strong> Byte 0 und Byte 1 des Adress-Headers.\n</li><li><strong>Codierung:</strong> Big-Endian (Network Byte Order, MSB in Byte 0, LSB in Byte 1).\n</li><li><strong>Semantik:</strong> Logische 16-Bit-Zieladresse (Empfänger-Steuergerät bzw. funktionale Multicast-/Broadcast-Adresse).\n</li></ul>\n</li><li><strong><code>Source Address (16 Bit)</code>:</strong>\n<ul class=\"fig-list\"><li><strong>Größe:</strong> 2 Byte (16 Bit).\n</li><li><strong>Position:</strong> Byte 2 und Byte 3 des Adress-Headers.\n</li><li><strong>Codierung:</strong> Big-Endian (Network Byte Order, MSB in Byte 2, LSB in Byte 3).\n</li><li><strong>Semantik:</strong> Logische 16-Bit-Quelladresse (sendendes Steuergerät).\n</li></ul>\n</li></ul>\n</li><li><strong>Beziehungen, Framing &amp; Kardinalitäten:</strong>\n<ul class=\"fig-list\"><li><strong>Gesamtbreite des Adress-Headers:</strong> Exakt 4 Byte.\n</li><li><strong>Kardinalität:</strong> 1:1-Paarung pro adressiertem N-PDU-Rahmen. Jeder Adress-Header besteht obligatorisch aus genau einer Target Address und genau einer Source Address.\n</li><li><strong>PDU-Strukturierung:</strong> Der Adress-Header steht unmittelbar am Anfang der N-PDU, gefolgt von der Protocol Control Information (N-PCI) und den Nutzdaten (N-Data):\n $$\\text{N-PDU} = \\text{Address Header (4 Bytes)} + \\text{N-PCI (1–5 Bytes)} + \\text{N-Data}$$\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Sende-Pfad (TX):</strong>\n<ol class=\"fig-list\"><li><strong>Trigger:</strong> <code>PduR</code> initiiert die Übertragung via <code>PduR_FrArTpTransmit(TxPduId, PduInfoPtr)</code>.\n</li><li><strong>Header-Generierung:</strong> Das Modul <code>FrArTp</code> prüft die für die Verbindung (<code>FrArTpConnection</code>) konfigurierte Adressierungsart. Bei aktivem 2-Byte-Format werden die konfigurierte Target Address (<code>FrArTpTargetAddress</code>) in Byte 0–1 und die Source Address (<code>FrArTpSourceAddress</code>) in Byte 2–3 des N-PDU-Puffers serialisiert.\n</li><li><strong>Framing &amp; N-PCI:</strong> Nachfolgend werden N-PCI (SF, FF, CF, FC) und SDU-Daten assembliert.\n</li><li><strong>Übergabe:</strong> Die serialisierte PDU wird via <code>FrIf_Transmit(FrTxPduId, &amp;PduInfo)</code> an das FlexRay-Interface übergeben.\n</li></ol>\n</li><li><strong>Empfangs-Pfad (RX) &amp; Filterung:</strong>\n<ol class=\"fig-list\"><li><strong>Trigger:</strong> Asynchrone Empfangsmeldung via <code>FrArTp_RxIndication(RxPduId, PduInfoPtr)</code> durch das <code>FrIf</code>.\n</li><li><strong>Parsing:</strong> Extraktion von Byte 0–1 (TA) und Byte 2–3 (SA).\n</li><li><strong>Adressfilterung:</strong> Abgleich von TA gegen die eigene konfigurierte Knotenadresse (physikalisch) oder Gruppenadressen (funktional).\n</li><li><strong>Routing:</strong> Zuordnung zur entsprechenden RX-Verbindungsinstanz (<code>FrArTpRxConnection</code>) anhand des Tupels <code>(Target Address, Source Address)</code>.\n</li><li><strong>Verwerfen/Fehlerfall:</strong> Passt TA nicht auf den lokalen Knoten oder ist kein passender Verbindungskontext konfiguriert, wird die PDU stillschweigend verworfen; bei Formatinkonsistenz oder PDU-Längenunterschreitung (&lt; 4 Byte Adress-Header + N-PCI) erfolgt ein Report an das Default Error Tracer Modul (<code>DET</code>).\n</li></ol>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Nutzdaten-Overhead &amp; PDU-Budgetierung:</strong>\n<ul class=\"fig-list\"><li>Der 2-Byte-Adress-Header verbraucht stets <strong>4 Byte Payload</strong> pro FlexRay-Frame. Bei festen statischen Slotgrößen (z. B. 16, 32 oder 64 Bytes) reduziert sich die maximale Transportdatenlänge pro Frame (Single Frame oder Consecutive Frame) entsprechend um 4 Bytes plus N-PCI-Länge.\n</li></ul>\n</li><li><strong>Endianness &amp; Byte-Order:</strong>\n<ul class=\"fig-list\"><li>AUTOSAR ComStack schreibt Network Byte Order (Big-Endian) vor. Treiber- und Stack-Entwickler müssen sicherstellen, dass 16-Bit-Ganzzahlwerte auf Little-Endian-Mikrocontrollern (z. B. ARM, TriCore) beim Serialisieren/Deserialisieren explizit gedreht werden.\n</li></ul>\n</li><li><strong>Konfigurationsanforderungen (BSW/ECUC):</strong>\n<ul class=\"fig-list\"><li>Parameter <code>FrArTpAddressFormatType</code>: Konfiguration auf <code>FRARTP_2_BYTE_ADDRESSING</code>.\n</li><li>Konsistenz zwischen <code>FrArTpTargetAddress</code> / <code>FrArTpSourceAddress</code> und den korrespondierenden Modulen (<code>PduR</code>, <code>Dcm</code>, DoFR).\n</li><li>Unterscheidung zum 1-Byte-Adressierungsmodus (<code>FRARTP_1_BYTE_ADDRESSING</code>): Das 2-Byte-Format erweitert den logischen Adressraum von 256 auf 65.536 Knoten, verdoppelt jedoch den Adress-Header-Overhead von 2 auf 4 Bytes.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-f73525d316a84a25", "releases": ["R20-11", "R21-11", "R22-11", "R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> PDU-Layout / Protokoll-Header-Spezifikation (Bit-/Byte-Felddefinition auf Protokollebene).\n</li><li><strong>Architektur-Kontext:</strong> \n<ul class=\"fig-list\"><li><strong>Plattform &amp; Schicht:</strong> AUTOSAR Classic Platform (Release R3.2.3), Communication Stack (ComStack).\n</li><li><strong>Modul:</strong> <code>FrArTp</code> (AUTOSAR FlexRay Transport Layer, Spezifikation SWS_FlexRayARTransportLayer nach ISO 10681-2).\n</li><li><strong>Funktionale Einordnung:</strong> Liegt zwischen dem PDU Router (<code>PduR</code>) als oberer Schicht und dem FlexRay Interface (<code>FrIf</code>) als unterer Schicht.\n</li><li><strong>Technischer Zweck:</strong> Definition des 32-Bit-Adress-Headers für N-PDUs im 2-Byte-Adressierungsmodus (<code>FRARTP_2_BYTE_ADDRESSING</code>). Dient der logischen Adressierung (Quell- und Ziel-Knotenidentifikation) für Punkt-zu-Punkt- (1:1) sowie Punkt-zu-Multipunkt-Verbindungen (1:n, funktional/Broadcast) über FlexRay-Netzwerke, typischerweise für Diagnosekommunikation (DoFR / UDS via ISO 14229) und Kalibrierung (XCP on FlexRay).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Dargestellte Datenstrukturen &amp; Felder:</strong>\n<ul class=\"fig-list\"><li><strong><code>Target Address (16 Bit)</code>:</strong>\n<ul class=\"fig-list\"><li><strong>Größe:</strong> 2 Byte (16 Bit).\n</li><li><strong>Position:</strong> Byte 0 und Byte 1 des Adress-Headers.\n</li><li><strong>Codierung:</strong> Big-Endian (Network Byte Order, MSB in Byte 0, LSB in Byte 1).\n</li><li><strong>Semantik:</strong> Logische 16-Bit-Zieladresse (Empfänger-Steuergerät bzw. funktionale Multicast-/Broadcast-Adresse).\n</li></ul>\n</li><li><strong><code>Source Address (16 Bit)</code>:</strong>\n<ul class=\"fig-list\"><li><strong>Größe:</strong> 2 Byte (16 Bit).\n</li><li><strong>Position:</strong> Byte 2 und Byte 3 des Adress-Headers.\n</li><li><strong>Codierung:</strong> Big-Endian (Network Byte Order, MSB in Byte 2, LSB in Byte 3).\n</li><li><strong>Semantik:</strong> Logische 16-Bit-Quelladresse (sendendes Steuergerät).\n</li></ul>\n</li></ul>\n</li><li><strong>Beziehungen, Framing &amp; Kardinalitäten:</strong>\n<ul class=\"fig-list\"><li><strong>Gesamtbreite des Adress-Headers:</strong> Exakt 4 Byte.\n</li><li><strong>Kardinalität:</strong> 1:1-Paarung pro adressiertem N-PDU-Rahmen. Jeder Adress-Header besteht obligatorisch aus genau einer Target Address und genau einer Source Address.\n</li><li><strong>PDU-Strukturierung:</strong> Der Adress-Header steht unmittelbar am Anfang der N-PDU, gefolgt von der Protocol Control Information (N-PCI) und den Nutzdaten (N-Data):\n $$\\text{N-PDU} = \\text{Address Header (4 Bytes)} + \\text{N-PCI (1–5 Bytes)} + \\text{N-Data}$$\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Sende-Pfad (TX):</strong>\n<ol class=\"fig-list\"><li><strong>Trigger:</strong> <code>PduR</code> initiiert die Übertragung via <code>PduR_FrArTpTransmit(TxPduId, PduInfoPtr)</code>.\n</li><li><strong>Header-Generierung:</strong> Das Modul <code>FrArTp</code> prüft die für die Verbindung (<code>FrArTpConnection</code>) konfigurierte Adressierungsart. Bei aktivem 2-Byte-Format werden die konfigurierte Target Address (<code>FrArTpTargetAddress</code>) in Byte 0–1 und die Source Address (<code>FrArTpSourceAddress</code>) in Byte 2–3 des N-PDU-Puffers serialisiert.\n</li><li><strong>Framing &amp; N-PCI:</strong> Nachfolgend werden N-PCI (SF, FF, CF, FC) und SDU-Daten assembliert.\n</li><li><strong>Übergabe:</strong> Die serialisierte PDU wird via <code>FrIf_Transmit(FrTxPduId, &amp;PduInfo)</code> an das FlexRay-Interface übergeben.\n</li></ol>\n</li><li><strong>Empfangs-Pfad (RX) &amp; Filterung:</strong>\n<ol class=\"fig-list\"><li><strong>Trigger:</strong> Asynchrone Empfangsmeldung via <code>FrArTp_RxIndication(RxPduId, PduInfoPtr)</code> durch das <code>FrIf</code>.\n</li><li><strong>Parsing:</strong> Extraktion von Byte 0–1 (TA) und Byte 2–3 (SA).\n</li><li><strong>Adressfilterung:</strong> Abgleich von TA gegen die eigene konfigurierte Knotenadresse (physikalisch) oder Gruppenadressen (funktional).\n</li><li><strong>Routing:</strong> Zuordnung zur entsprechenden RX-Verbindungsinstanz (<code>FrArTpRxConnection</code>) anhand des Tupels <code>(Target Address, Source Address)</code>.\n</li><li><strong>Verwerfen/Fehlerfall:</strong> Passt TA nicht auf den lokalen Knoten oder ist kein passender Verbindungskontext konfiguriert, wird die PDU stillschweigend verworfen; bei Formatinkonsistenz oder PDU-Längenunterschreitung (&lt; 4 Byte Adress-Header + N-PCI) erfolgt ein Report an das Default Error Tracer Modul (<code>DET</code>).\n</li></ol>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Nutzdaten-Overhead &amp; PDU-Budgetierung:</strong>\n<ul class=\"fig-list\"><li>Der 2-Byte-Adress-Header verbraucht stets <strong>4 Byte Payload</strong> pro FlexRay-Frame. Bei festen statischen Slotgrößen (z. B. 16, 32 oder 64 Bytes) reduziert sich die maximale Transportdatenlänge pro Frame (Single Frame oder Consecutive Frame) entsprechend um 4 Bytes plus N-PCI-Länge.\n</li></ul>\n</li><li><strong>Endianness &amp; Byte-Order:</strong>\n<ul class=\"fig-list\"><li>AUTOSAR ComStack schreibt Network Byte Order (Big-Endian) vor. Treiber- und Stack-Entwickler müssen sicherstellen, dass 16-Bit-Ganzzahlwerte auf Little-Endian-Mikrocontrollern (z. B. ARM, TriCore) beim Serialisieren/Deserialisieren explizit gedreht werden.\n</li></ul>\n</li><li><strong>Konfigurationsanforderungen (BSW/ECUC):</strong>\n<ul class=\"fig-list\"><li>Parameter <code>FrArTpAddressFormatType</code>: Konfiguration auf <code>FRARTP_2_BYTE_ADDRESSING</code>.\n</li><li>Konsistenz zwischen <code>FrArTpTargetAddress</code> / <code>FrArTpSourceAddress</code> und den korrespondierenden Modulen (<code>PduR</code>, <code>Dcm</code>, DoFR).\n</li><li>Unterscheidung zum 1-Byte-Adressierungsmodus (<code>FRARTP_1_BYTE_ADDRESSING</code>): Das 2-Byte-Format erweitert den logischen Adressraum von 256 auf 65.536 Knoten, verdoppelt jedoch den Adress-Header-Overhead von 2 auf 4 Bytes.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-cfebc6be27fb2711", "to": "FIG-8e478ed3be09459c", "fr": "R3.2.3", "tr": "R4.1.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li><strong>Header-Beschriftung:</strong> Ergänzung der Beschriftung „2 Byte Addressing Not compliant to ISO 15765-2“ oberhalb der Adressfelder.\n</li></ul>"}, {"from": "FIG-8e478ed3be09459c", "to": "FIG-63e787954ff327e2", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-63e787954ff327e2", "to": "FIG-f73525d316a84a25", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
